Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_clear_clears_buffer_contents(void) {
    // Setup: create a buffer with nonzero data
    buffer_t *buf = buffer_new_with_copy("Hello, world!");
    TEST_ASSERT_NOT_NULL(buf);

    // Precondition: buffer contains the original string
    helper_assert_buffer_data_equals(buf, "Hello, world!");
    size_t orig_size = buffer_size(buf);

    // Test: clear the buffer
    buffer_clear(buf);

    // Assert: buffer is filled with zeroes, size is unchanged, length is zero
    helper_assert_buffer_filled_with(buf, 0);
    helper_assert_buffer_size(buf, orig_size);
    helper_assert_buffer_length(buf, 0);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_clear_clears_buffer_contents);
    return UNITY_END();
}

